// Some portions generated by Codex
package org.eclipse.rdf4j.query.parser.sparql;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.List;

import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.helpers.collectors.StatementPatternCollector;
import org.eclipse.rdf4j.query.parser.ParsedQuery;
import org.junit.jupiter.api.Test;

public class PrefixDeclProcessorTest {

	private final SPARQLParser parser = new SPARQLParser();

	@Test
	public void testEveryPnLocalEscapeIsUnescaped() {
		String escapable = "_~.-!$&'()*+,;=/?#@%";
		StringBuilder qname = new StringBuilder("ex:");
		StringBuilder expected = new StringBuilder("urn:test:");

		for (int i = 0; i < escapable.length(); i++) {
			char c = escapable.charAt(i);
			qname.append('\\').append(c);
			expected.append(c);
		}

		assertEquals(expected.toString(), parseSubject(qname.toString()));
	}

	@Test
	public void testEscapedDollarDoesNotBecomeARegexReplacement() {
		assertEquals("urn:test:a$b", parseSubject("ex:a\\$b"));
	}

	private String parseSubject(String qname) {
		ParsedQuery query = parser.parseQuery(
				"PREFIX ex: <urn:test:> ASK { " + qname + " ex:p ex:o }", null);
		List<StatementPattern> patterns = StatementPatternCollector.process(query.getTupleExpr());
		assertEquals(1, patterns.size());
		return patterns.get(0).getSubjectVar().getValue().stringValue();
	}
}
